import{_ as o,C as t,o as i,c as n,ak as r,E as s}from"./chunks/framework.BNVJvTzl.js";const y=JSON.parse('{"title":"Labor efficiency ratio (LER) for agencies","description":"What labor efficiency ratio measures, how to calculate it, and a free calculator: the gross margin your agency earns for every dollar of delivery pay.","frontmatter":{"title":"Labor efficiency ratio (LER) for agencies","description":"What labor efficiency ratio measures, how to calculate it, and a free calculator: the gross margin your agency earns for every dollar of delivery pay."},"headers":[],"relativePath":"learn/ler.md","filePath":"learn/ler.md"}'),l={name:"learn/ler.md"};function h(c,e,d,u,p,f){const a=t("LerCalculator");return i(),n("div",null,[e[0]||(e[0]=r('<h1 id="labor-efficiency-ratio-for-agencies" tabindex="-1">Labor efficiency ratio for agencies <a class="header-anchor" href="#labor-efficiency-ratio-for-agencies" aria-label="Permalink to &quot;Labor efficiency ratio for agencies&quot;">​</a></h1><p>Labor efficiency ratio, or LER, answers one question: for every dollar you pay the people who do client work, how many dollars of gross margin does that work bring back? Utilization tells you whether people are busy. LER tells you whether busy is profitable.</p><h2 id="the-formula" tabindex="-1">The formula <a class="header-anchor" href="#the-formula" aria-label="Permalink to &quot;The formula&quot;">​</a></h2><p><strong>LER = gross margin ÷ direct labor</strong></p><ul><li><strong>Gross margin</strong> is revenue minus what you paid outside parties for the work: vendors and contractors on a fixed fee, and other costs you pass through to the client.</li><li><strong>Direct labor</strong> is what you pay the people who do client work, for the same period: employees&#39; pay, and contractors paid by the hour.</li></ul><p>This is Greg Crabtree&#39;s definition, from <em>Simple Numbers, Straight Talk, Big Profits!</em>, and it&#39;s the one VERA uses everywhere it shows LER. VERA counts pay before payroll taxes and benefits. Some published benchmarks include them, which makes the ratio lower, so check which one you&#39;re comparing against.</p><h2 id="work-out-yours" tabindex="-1">Work out yours <a class="header-anchor" href="#work-out-yours" aria-label="Permalink to &quot;Work out yours&quot;">​</a></h2>',7)),s(a),e[1]||(e[1]=r('<h2 id="an-example" tabindex="-1">An example <a class="header-anchor" href="#an-example" aria-label="Permalink to &quot;An example&quot;">​</a></h2><p>An agency brings in $1,500,000 a year. It pays $200,000 to contractors and vendors on fixed fees, so its gross margin is $1,300,000. It pays its delivery team $520,000. Its LER is $1,300,000 ÷ $520,000 = 2.50x: every dollar of delivery pay brings back $2.50 of gross margin.</p><h2 id="is-my-number-good" tabindex="-1">Is my number good? <a class="header-anchor" href="#is-my-number-good" aria-label="Permalink to &quot;Is my number good?&quot;">​</a></h2><p>There&#39;s no single healthy LER worth publishing. The right target depends on your service mix, your pricing and where you&#39;re starting from. Set your own target and watch the trend: an LER that&#39;s rising means the same team is producing more margin. In VERA you set a company target, and a different one for any project that needs it.</p><h2 id="where-ler-leaks" tabindex="-1">Where LER leaks <a class="header-anchor" href="#where-ler-leaks" aria-label="Permalink to &quot;Where LER leaks&quot;">​</a></h2><ul><li><strong>Senior people doing junior work.</strong> Expensive hours producing work that a junior could do.</li><li><strong>Work nobody priced.</strong> Scope creep, rework and hours that never reach an invoice.</li><li><strong>Decisions that wait on the owner.</strong> The team is paid while the work waits.</li></ul><p>Tom Hart, who built VERA, writes about the levers that move it in <a href="https://hartops.com/blog/labor-efficiency-ratio-explained/" target="_blank" rel="noreferrer">Labor Efficiency Ratio, Explained</a>.</p><h2 id="ler-in-vera" tabindex="-1">LER in VERA <a class="header-anchor" href="#ler-in-vera" aria-label="Permalink to &quot;LER in VERA&quot;">​</a></h2><p>VERA works out LER from every recorded hour: by project, by client, by discipline and by project manager, against your target, with a monthly trend. Project managers see the ratio for their own projects and never anyone&#39;s pay. <a href="/features.html">See every feature →</a></p><p><a href="https://calendly.com/getvera" target="_blank" rel="noreferrer"><strong>Book a 30-minute call →</strong></a></p>',10))])}const g=o(l,[["render",h]]);export{y as __pageData,g as default};
